mapper.select:
 	select LOGIN_ID,USER_ID,EMAIL,PASSWORD,NAME,STATUS,CREATED_AT,UPDATED_AT,ADMIN_AT,POINTS,rnum
	from(
	  select LOGIN_ID,USER_ID,EMAIL,PASSWORD,NAME,STATUS,CREATED_AT,UPDATED_AT,ADMIN_AT,POINTS,rownum rnum
        from(select LOGIN_ID,USER_ID,EMAIL,PASSWORD,NAME,STATUS,CREATED_AT,UPDATED_AT,ADMIN_AT,POINTS
           	 from users

			 order by created_At)
		)where #{firstRecordIndex} <= rnum and rnum <= #{lastRecordIndex}

select LOGIN_ID
from users
where NAME = #{name} AND Email = #{email}

select LOGIN_ID,EMAIL,NAME
from users
where LOGIN_ID = #{loginId} AND NAME = #{name} AND Email = #{email}

SELECT CASE WHEN COUNT(*)> 0 THEN 1 ELSE 0 END
FROM users
Where LOGIN_ID = #{id}

SELECT LOGIN_ID
FROM users
where password = #{password} and login_Id = #{loginId}

mapper.update:
update users
set password = #{password}
where EMAIL = #{email}

update users
set password = #{newPassword}
where LOGIN_ID = #{loginId}
